<?php
require_once __DIR__.'/app/config/Conexion.php';require_once __DIR__.'/app/helpers.php';require_once __DIR__.'/app/dao/PedidoDAO.php';
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: vinos.php');exit;}check_csrf();$error='';$id=0;
$nombre=trim($_POST['nombre']??'');$email=trim($_POST['email']??'');$telefono=trim($_POST['telefono']??'');$modalidad=$_POST['modalidad']??'';$mayor=$_POST['mayor_edad']??'';$items=json_decode($_POST['items']??'',true);
if(mb_strlen($nombre)<2)$error='Ingresá tu nombre.';elseif(!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Ingresá un email válido.';elseif(mb_strlen($telefono)<6)$error='Ingresá un teléfono válido.';elseif($mayor!=='si')$error='Confirmá que sos mayor de 18 años.';elseif(!in_array($modalidad,['Retiro por el local','Envío a domicilio'],true))$error='Elegí cómo preferís recibir tu pedido.';elseif(!is_array($items)||!$items)$error='Tu selección está vacía.';
if(!$error){try{$id=(new PedidoDAO(Conexion::obtener()))->crear(['nombre'=>$nombre,'email'=>$email,'telefono'=>$telefono,'modalidad'=>$modalidad,'domicilio'=>'','nota'=>''],$items);}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'No pudimos registrar tu pedido. Revisá que MySQL esté iniciado y volvé a intentarlo.';}}
$paginaActiva='pedido';$tituloPagina=$error?'Revisar pedido':'Pedido recibido';require __DIR__.'/partials/header.php';
?>
<section class="result-page"><span class="result-mark"><?= $error?'!':'✳' ?></span><p class="eyebrow"><?= $error?'UN DETALLE MÁS':'GRACIAS POR ELEGIRNOS' ?></p><h1><?= $error?'Revisemos tu pedido.':'Tu pedido ya está en la Bodeguita.' ?></h1><p><?= $error?h($error):'Recibimos tu solicitud #'.(int)$id.'. Te contactaremos para confirmar disponibilidad, forma de pago y coordinación de entrega o retiro.' ?></p><p class="result-note">El pedido queda pendiente de confirmación y no se realiza ningún cobro en línea.</p><a class="hero-button" href="vinos.php">Volver a los vinos ↗</a><?php if(!$error): ?><script>localStorage.removeItem('bodeguita-cart-v2')</script><?php endif; ?></section>
